use warnings;
use utf8;
use FindBin;
use lib "$FindBin::Bin";
use Palindrome qw(is_palindrome);

while (my $line = <STDIN>) {
    chomp $line;
    next if $line =~ /^\s*$/;   # skip blank lines
    print $line, ' => ',
      is_palindrome($line) ? 'palindrome' : 'not a palindrome', "\n";
