import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;

public class LineCounter {

    private static final String DELIMITER = "\n";

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter the text to search (type a line containing only a slash / to end it): ");
        if (!scanner.hasNextLine()) {
            System.err.println("Error: no input provided.");
            System.exit(1);
        }

        String text = readLine(scanner, "Text: ");
        if (!hasSlash(text)) {
            System.err.println("Error: text must contain at least one '/' to mark the end.");
            System.exit(1);
        }

        String[] lines = text.split(DELIMITER, -1);
        // split drops the trailing empty string, so we add it back for the last line if it was there.
        if (text.endsWith(DELIMITER) && !lines[lines.length - 1].isEmpty()) {
            lines = append(lines, "");
        }

        System.out.print("Enter the regular expression: ");

        if (!scanner.hasNextLine()) {
            System.err.println("Error: no pattern provided.");
            System.exit(1);
        }

        String patternInput = readLine(scanner, "Pattern: ");
        if (!hasSlash(patternInput)) {
            System.err.println("Error: pattern must contain at least one '/' to mark the end.");
            System.exit(1);
        }

        String pattern = unescape(patternInput);

        List<Integer> counts = new ArrayList<>();
        List<String> matchedLines = new ArrayList<>();

        try {
            Pattern compiled = Pattern.compile(pattern);
            int lineNo = 1;

            for (String line : lines) {
                int count = 0;
                Matcher matcher = compiled.matcher(line);
                while (matcher.find()) {
                    count++;
                }
                counts.add(count);
                if (count > 0) {
                    matchedLines.add(line);
                }
                lineNo++;
            }

        } catch (PatternSyntaxException e) {
            System.err.println("Error: invalid regular expression '" + pattern + "'.");
            System.err.println("Details: " + e.getMessage());
            System.exit(1);
        }

        int total = counts.stream().mapToInt(i -> i).sum();
        System.out.println();
        System.out.println("Results for '" + pattern + "':");
        System.out.println("Total matches: " + total);
        System.out.println("Lines containing matches: " + matchedLines.size());
        System.out.println();

        if (total == 0) {
            System.out.println("No matches found.");
        } else {
            System.out.println("Matched lines:");
            int maxWidth = String.valueOf(total).length();
            for (int i = 0; i < counts.size(); i++) {
                System.out.printf("%4d: %s%n", counts.get(i), escaped(lines[i]));
            }
        }

        scanner.close();
    }

    private static String readLine(Scanner scanner, String prompt) {
        System.out.print(prompt);
        return scanner.nextLine();
    }

    private static boolean hasSlash(String s) {
        return s.contains("/");
    }

    private static String unescape(String s) {
        int first = s.indexOf('/');
        int last = s.lastIndexOf('/');
        if (first == last) {
            return s.substring(0, first);
        }
        return s.substring(first + 1, last);
    }

    private static String[] append(String[] array, String element) {
        String[] result = new String[array.length + 1];
        System.arraycopy(array, 0, result, 0, array.length);
        result[result.length - 1] = element;
        return result;
    }

    private static String escaped(String s) {
        return "\"" + s.replace("\\", "\\\\")
                       .replace("\"", "\\\"")
                       .replace("\n", "\\n")
                       .replace("\r", "\\r") + "\"";
    }
}
