This program reads a CSV file and draws it as a formatted table. It takes care of missing values, numbers and dates, and widens each column just enough to hold its data.

```python
#!/usr/bin/env python3
"""Read a CSV file and print it as a formatted table."""

import csv
import sys
from datetime import datetime, date
from decimal import Decimal, InvalidOperation


def parse_field(value):
    """Convert a string field to a sensible Python type.

    Strings that look like dates, numbers or booleans are converted.
    Empty fields and 'NA' become None, which the table renderer treats
    as a missing value.
    """
    value = value.strip()
    if not value or value.upper() == "NA":
        return None

    # Dates
    for fmt in ("%Y-%m-%d", "%Y/%m/%d", "%d-%m-%Y", "%d/%m/%Y", "%Y-%m-%dT%H:%M:%S"):
        try:
            return datetime.strptime(value, fmt).date()
        except ValueError:
            pass

    # Integers and decimals, including negative numbers and numbers with a sign
    if value.lstrip("-+").replace(".", "", 1).isdigit():
        try:
            return int(value)
        except ValueError:
            try:
                return float(value)
            except ValueError:
                pass

    # Booleans
    if value.lower() in {"true", "yes", "1"}:
        return True
    if value.lower() in {"false", "no", "0"}:
        return False

    return value


def read_csv(path):
    """Read the CSV, detecting its quoting style from the first line.

    Returns (field_names, rows) where rows is a list of dicts.
    """
    try:
        f = open(path, encoding="utf-8-sig", newline="")
    except OSError as e:
        raise OSError(f"Cannot open '{path}': {e}") from e

    try:
        first_line = f.readline()
        if not first_line.strip():
            raise ValueError("The file is empty.")
        f.seek(0)

        dialect = csv.Sniffer().sniff(first_line)
        reader = csv.DictReader(f, dialect=dialect)

        if reader.fieldnames is None:
            raise ValueError("No header row found.")

        field_names = list(reader.fieldnames)
        rows = [
            {k: parse_field(v) for k, v in row.items()}
            for row in reader
        ]

    except csv.Error as e:
        raise ValueError(f"Malformed CSV at line {e.lineno}: {e}") from e
    finally:
        f.close()

    return field_names, rows


def table_width(field_names, rows):
    """Return the width of each column in characters."""
    widths = {name: len(name) for name in field_names}
    for row in rows:
        for name in field_names:
            cell = row.get(name)
            cell_width = len(str(cell) if cell is not None else "")
            if cell_width > widths[name]:
                widths[name] = cell_width
    return widths


def render_row(fields, widths, hrule=""):
    """Return one row as a string.

    If a field is missing, it is printed as blank. This keeps the
    columns in step, which matters when a row is split across lines.
    """
    parts = []
    for name in fields:
        cell = hrule.get(name)
        if cell is None:
            cell = " " * widths[name]
        parts.append(cell)
    return "| " + " | ".join(parts) + " |"


def format_cell(value, width):
    """Turn a value into a left-aligned string of the given width."""
    s = "" if value is None else str(value)
    return s.ljust(width)


def render_table(field_names, rows, hrule=None):
    """Yield the lines of the table, one per line."""
    if hrule is None:
        hrule = {}
    widths = table_width(field_names, rows)
    header = render_row(field_names, widths)
    separator = render_row(hrule, widths, hrule={"-": "-" * (widths[name] + 2) for name in field_names})
    body = (render_row(row, widths) for row in rows)

    yield header
    yield separator
    yield from body


def main():
    if len(sys.argv) < 2:
        sys.exit(f"Usage: {sys.argv[0]} file.csv [file2.csv ...]")

    for path in sys.argv[1:]:
        if path.endswith((".csv", ".tsv")):
            try:
                field_names, rows = read_csv(path)
            except OSError as e:
                sys.stderr.write(f"{e}\n")
                continue
        else:
            sys.stderr.write(f"Skipped '{path}': not a CSV or TSV file.\n")
            continue

        if not rows:
            sys.stderr.write(f"Warning: '{path}' has no data rows.\n")

        title = f"  {path.split('/')[-1]}  "
        frame = "+" + (len(field_names) + 1) * "-" + "+"
        print()
        print(frame)
        print("|", title.center(sum(widths.values()) + 3 * len(field_names) - 1), "|")
        print(frame)
        for line in render_table(field_names, rows):
            print(line)
        print(frame)


if __name__ == "__main__":
    main()
```

