```python
# grid_paths.py
# Count the number of paths from the top-left cell to every other cell,
# moving only right and down, while staying out of the cells marked 1.
# Input: a grid of 0s and 1s, given as N lines of space-separated values.
# Output: a grid of the same size, with the path counts.
# Usage: python grid_paths.py [input_file]
# Without a file argument, it reads from standard input.

import sys


def read_grid():
    """Read a grid of 0s and 1s from a file or from standard input.

    Returns a list of lists of integers, or None on a bad line.
    """
    if len(sys.argv) > 1:
        try:
            f = open(sys.argv[1])
        except OSError as e:
            sys.exit(f"cannot open {sys.argv[1]}: {e}")
    else:
        f = sys.stdin

    grid = []
    for line in f:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        try:
            row = [int(x) for x in parts]
        except ValueError as e:
            sys.exit(f"bad number in input: {e}")
        grid.append(row)

    if not grid:
        sys.exit("the input contains no rows")
    return grid


def count_paths(grid):
    """Return a grid of path counts, with the same shape as the input.

    Every entry is 0 where the input has a 1.
    """
    n = len(grid)
    m = len(grid[0])
    # Every other row has the same length as the first.
    for r in range(1, n):
        if len(grid[r]) != m:
            sys.exit(f"row {r} has a different length from row 0")

    counts = [[0] * m for _ in range(n)]

    # The top-left cell gets 1 if it is open.
    if grid[0][0] == 0:
        counts[0][0] = 1

    # First row, left to right. Each cell can only be reached from the left.
    for c in range(1, m):
        if grid[0][c] == 0:
            counts[0][c] = counts[0][c - 1]

    # The rest of the grid, top to bottom and left to right.
    for r in range(1, n):
        for c in range(m):
            if grid[r][c] == 0:
                up = counts[r - 1][c]
                left = counts[r][c - 1] if c > 0 else 0
                counts[r][c] = up + left

    return counts


def write_grid(grid):
    """Write a grid of integers to standard output, one row per line."""
    for row in grid:
        print(" ".join(str(x) for x in row))


def main():
    grid = read_grid()
    if grid is None:
        sys.exit("reading failed")
    counts = count_paths(grid)
    write_grid(counts)


if __name__ == "__main__":
    main()
```

